import uuid, time

HOLDS = {}  # key: (unit_id, date) -> {token, expires_at}
HOLD_TTL_SEC = 480

def try_hold(unit_id: str, date: str) -> str | None:
    now = time.time()
    key = (unit_id, date)
    cur = HOLDS.get(key)
    # Lazy expiry: owner of the store owns the timeout, not payment callback.
    if cur and cur["expires_at"] < now:
        del HOLDS[key]
        cur = None
    if cur:
        return None  # already held -> do NOT queue silently, tell user why
    token = str(uuid.uuid4())
    HOLDS[key] = {"token": token, "expires_at": now + HOLD_TTL_SEC}
    return token

